import Foundation

/// Языки интерфейса. Ключ перевода — русская строка-источник (RU = ключ, без записи в таблицу).
enum Lang: String, CaseIterable {
    case ru, uk, en, pt
    var title: String {
        switch self {
        case .ru: return "Русский"
        case .uk: return "Українська"
        case .en: return "English"
        case .pt: return "Português (Brasil)"
        }
    }
}

enum I18n {
    private static let d = UserDefaults.standard

    /// Текущий язык: ручной выбор (app.lang) или авто-определение по системным предпочтениям.
    static var current: Lang = resolve()

    /// nil = «по системе».
    static var override: Lang? {
        get { d.string(forKey: "app.lang").flatMap(Lang.init) }
        set { d.set(newValue?.rawValue, forKey: "app.lang"); current = resolve() }
    }

    static func resolve() -> Lang {
        if let e = ProcessInfo.processInfo.environment["BM_LANG"], let l = Lang(rawValue: e) { return l }   // для проверки
        if let o = d.string(forKey: "app.lang").flatMap(Lang.init) { return o }
        for code in Locale.preferredLanguages {
            let lc = code.lowercased()
            if lc.hasPrefix("uk") { return .uk }
            if lc.hasPrefix("en") { return .en }
            if lc.hasPrefix("pt") { return .pt }
            if lc.hasPrefix("ru") { return .ru }
        }
        return .ru
    }

    // MARK: динамические строки (число/склонение)
    private static func slavic(_ n: Int, _ a: String, _ b: String, _ c: String) -> String {
        let n10 = n % 10, n100 = n % 100
        if n10 == 1 && n100 != 11 { return a }
        if (2...4).contains(n10) && !(12...14).contains(n100) { return b }
        return c
    }
    static func days(_ n: Int) -> String {
        switch current {
        case .ru: return "\(n) " + slavic(n, "день", "дня", "дней")
        case .uk: return "\(n) " + slavic(n, "день", "дні", "днів")
        case .en: return "\(n) day" + (n == 1 ? "" : "s")
        case .pt: return "\(n) dia" + (n == 1 ? "" : "s")
        }
    }
    static func trialStatus(_ n: Int) -> String {
        switch current {
        case .ru: return "Пробный период — осталось \(days(n))"
        case .uk: return "Пробний період — залишилось \(days(n))"
        case .en: return "Trial — \(days(n)) left"
        case .pt: return "Período de teste — restam \(days(n))"
        }
    }
    static func proMenuTrial(_ n: Int) -> String {
        switch current {
        case .ru: return "Kelvin Pro — осталось \(days(n))"
        case .uk: return "Kelvin Pro — залишилось \(days(n))"
        case .en: return "Kelvin Pro — \(days(n)) left"
        case .pt: return "Kelvin Pro — restam \(days(n))"
        }
    }
    static func proFeatureTitle(_ name: String) -> String {
        switch current {
        case .ru: return "«\(name)» — функция Kelvin Pro"
        case .uk: return "«\(name)» — функція Kelvin Pro"
        case .en: return "\u{201C}\(name)\u{201D} is a Kelvin Pro feature"
        case .pt: return "\u{201C}\(name)\u{201D} é um recurso do Kelvin Pro"
        }
    }
    static func trialActiveNote(_ n: Int) -> String {
        switch current {
        case .ru: return "Пробный период активен — \(days(n)) полного доступа. Купить можно в любой момент, прогресс не теряется."
        case .uk: return "Пробний період активний — \(days(n)) повного доступу. Придбати можна будь-коли, прогрес не втрачається."
        case .en: return "Trial is active — \(days(n)) of full access. You can buy anytime; nothing is lost."
        case .pt: return "Teste ativo — \(days(n)) de acesso total. Compre quando quiser; nada se perde."
        }
    }
}

/// Перевод по ключу-русской-строке. RU → ключ; uk/en/pt → из таблицы; нет перевода → RU-ключ.
func L(_ key: String) -> String {
    if I18n.current == .ru { return key }
    if let row = Strings.table[key], let v = row[I18n.current] { return v }
    return key
}

