        "Kelvin — диагностический отчёт": [.uk: "Kelvin — діагностичний звіт", .en: "Kelvin — diagnostic report", .pt: "Kelvin — relatório de diagnóstico"],
        "Модель": [.uk: "Модель", .en: "Model", .pt: "Modelo"],
        "Безопасность": [.uk: "Безпека", .en: "Security", .pt: "Segurança"],
